vec2 ab = b - a;
vec2 ac = c - a;
vec2 ap = p - a;

double det = ab.x * ac.y - ab.y * ac.x;
if (std::abs(det) < 1e-10) return vec3(-1, 1, 1);

double inv_det = 1.0 / det;
double u = (ap.x * ac.y - ap.y * ac.x) * inv_det;
double v = (ab.x * ap.y - ab.y * ap.x) * inv_det;
double w = 1.0 - u - v;

return vec3(w, u, v);

